#'
#' @export
pyoutlierdetection <- function(
    data,
    vars = NULL,
    method = "zscore_robust",
    zscore_threshold = 3.29,
    iqr_multiplier = 1.7,
    showRows = FALSE,
    showPlot = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyoutlierdetection requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- pyoutlierdetectionOptions$new(
        vars = vars,
        method = method,
        zscore_threshold = zscore_threshold,
        iqr_multiplier = iqr_multiplier,
        showRows = showRows,
        showPlot = showPlot,
        showConsole = showConsole)

    analysis <- pyoutlierdetectionClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

